mapper.select:
select distinct t1.id, t1.production_plan_id, t1.start_time, t1.end_time, t1.procedure_list, t1.production_line_id, t1.production_line_code, t1.production_line_name, t2.plan_no, t2.batch_no, t2.process_name, t2.process_version from bm_production_plan_item as t1 left join bm_product_plan as t2 on t2.production_plan_item_id = t1.id left join bm_resource_permission t3 on t3.resource_id = t2.process_id where t1.is_deleted = 0 and t2.status != 'DISCARD' and ((YEAR(t1.start_time) <= #{year} AND YEAR(t1.end_time) >= #{year}) OR (YEAR(t1.start_time) = #{year} OR YEAR(t1.end_time) = #{year}))
and t3.dept_id in
#{deptId}
and t1.production_plan_id = #{productionPlanId}
and t1.id = #{productionPlanItemId}
AND (t1.start_time <= LAST_DAY(STR_TO_DATE(CONCAT(#{year}, '-', #{month}, '-01'), '%Y-%m-%d')) AND t1.end_time >= STR_TO_DATE(CONCAT(#{year}, '-', #{month}, '-01'), '%Y-%m-%d'))
and t2.process_id =#{processId}
order by t1.start_time asc

select distinct t1.id, t1.production_plan_id, t1.start_time, t1.end_time, t1.procedure_list, t1.production_line_id, t1.production_line_code, t1.production_line_name, t2.plan_no, t2.batch_no, t2.process_name, t2.process_version from bm_production_plan_item as t1 left join bm_product_plan as t2 on t2.production_plan_item_id = t1.id left join bm_resource_permission t3 on t3.resource_id = t2.process_id where t1.is_deleted = 0 and t2.status != 'DISCARD' AND (t1.start_time <= LAST_DAY(STR_TO_DATE(CONCAT(#{endMonth}, '-01'), '%Y-%m-%d')) AND t1.end_time >= STR_TO_DATE(CONCAT(#{startMonth}, '-01'), '%Y-%m-%d'))
and t3.dept_id in
#{deptId}
and t1.production_plan_id = #{productionPlanId}
and t1.id = #{productionPlanItemId}
and t2.process_id =#{processId}
order by t1.start_time asc
